=PREFIX risk: <http://example.org/privacy-risk#>
PREFIX rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>

INSERT DATA {

  ### Severity Levels ###
  risk:High   a risk:SeverityLevel ; rdfs:label "High" .
  risk:Medium a risk:SeverityLevel ; rdfs:label "Medium" .
  risk:Low    a risk:SeverityLevel ; rdfs:label "Low" .

  ### Taxonomy ###
  risk:PrivacyRiskTaxonomy001 a risk:PrivacyRiskTaxonomy ;
      rdfs:label "Data Privacy Risks in Multi-Agent AI Systems" ;
      risk:hasCategory
          risk:GovernanceComplianceRisks ,
          risk:ArchitecturalDataFlowRisks ,
          risk:AutonomyDecisionMakingRisks ,
          risk:AdversarialSecurityExploitRisks .

  ### ─────────────────────────────────────────
  ### Governance & Compliance Risks
  ### ─────────────────────────────────────────

  risk:GovernanceComplianceRisks a risk:RiskCategory ;
      rdfs:label "Governance and Compliance Risks" ;
      risk:hasRisk
          risk:RegulatoryNonCompliance ,
          risk:AccountabilityOversightGaps ,
          risk:TrustConsentManagementFailures .

  risk:RegulatoryNonCompliance a risk:PrivacyRisk ;
      rdfs:label "Regulatory Non-Compliance" ;
      risk:hasSeverity risk:High ;
      risk:frequencyPercent "14"^^xsd:decimal ;
      risk:definition "Failures to adhere to privacy, security, or data protection laws." .

  risk:AccountabilityOversightGaps a risk:PrivacyRisk ;
      rdfs:label "Accountability and Oversight Gaps" ;
      risk:hasSeverity risk:High ;
      risk:frequencyPercent "11"^^xsd:decimal ;
      risk:definition "Lack of clear roles, responsibilities, or governance mechanisms for AI accountability." .

  risk:TrustConsentManagementFailures a risk:PrivacyRisk ;
      rdfs:label "Trust and Consent Management Failures" ;
      risk:hasSeverity risk:Medium ;
      risk:frequencyPercent "7"^^xsd:decimal ;
      risk:definition "Failures to maintain user trust, obtain valid consent, or manage dynamic consent requirements." .

  ### ─────────────────────────────────────────
  ### Architectural & Data Flow Risks
  ### ─────────────────────────────────────────

  risk:ArchitecturalDataFlowRisks a risk:RiskCategory ;
      rdfs:label "Architectural and Data Flow Risks" ;
      risk:hasRisk
          risk:DataAggregationReidentification ,
          risk:PIIDetectionRemediationFailures ,
          risk:ExpandedAttackSurfaceExposure ,
          risk:InterAgentCommunicationStateRisks .

  risk:DataAggregationReidentification a risk:PrivacyRisk ;
      rdfs:label "Data Aggregation and Re-identification" ;
      risk:hasSeverity risk:High ;
      risk:frequencyPercent "13"^^xsd:decimal ;
      risk:definition "Combining datasets enables identity exposure through linkage attacks." .

  risk:PIIDetectionRemediationFailures a risk:PrivacyRisk ;
      rdfs:label "PII Detection and Remediation Failures" ;
      risk:hasSeverity risk:High ;
      risk:frequencyPercent "9"^^xsd:decimal ;
      risk:definition "Failures to identify, remove, or protect sensitive data within AI pipelines." .

  risk:ExpandedAttackSurfaceExposure a risk:PrivacyRisk ;
      rdfs:label "Expanded Attack Surface and Exposure Vectors" ;
      risk:hasSeverity risk:Medium ;
      risk:frequencyPercent "7"^^xsd:decimal ;
      risk:definition "Increased exposure due to multi-agent communication, integrations, and autonomous operations." .

  risk:InterAgentCommunicationStateRisks a risk:PrivacyRisk ;
      rdfs:label "Inter-Agent Communication and State Management Risks" ;
      risk:hasSeverity risk:Medium ;
      risk:frequencyPercent "5"^^xsd:decimal ;
      risk:definition "Privacy risks arising from how agents share, store, or reuse internal state." .

  ### ─────────────────────────────────────────
  ### Autonomy & Decision-Making Risks
  ### ─────────────────────────────────────────

  risk:AutonomyDecisionMakingRisks a risk:RiskCategory ;
      rdfs:label "Autonomy and Decision-Making Risks" ;
      risk:hasRisk
          risk:ExplainabilityOpacityChallenges ,
          risk:AutonomyMisalignmentOverreach ,
          risk:BiasFairnessRisks .

  risk:ExplainabilityOpacityChallenges a risk:PrivacyRisk ;
      rdfs:label "Explainability and Opacity Challenges" ;
      risk:hasSeverity risk:Medium ;
      risk:frequencyPercent "11"^^xsd:decimal ;
      risk:definition "Lack of transparency in how agents reason, especially when personal data is involved." .

  risk:AutonomyMisalignmentOverreach a risk:PrivacyRisk ;
      rdfs:label "Autonomy Misalignment and Overreach" ;
      risk:hasSeverity risk:Medium ;
      risk:frequencyPercent "7"^^xsd:decimal ;
      risk:definition "Agents operate beyond intended boundaries or misinterpret objectives involving personal data." .

  risk:BiasFairnessRisks a risk:PrivacyRisk ;
      rdfs:label "Bias and Fairness Risks" ;
      risk:hasSeverity risk:Medium ;
      risk:frequencyPercent "7"^^xsd:decimal ;
      risk:definition "Unfair or discriminatory outcomes driven by skewed data or reasoning processes." .

  ### ─────────────────────────────────────────
  ### Adversarial & Security Exploit Risks
  ### ─────────────────────────────────────────

  risk:AdversarialSecurityExploitRisks a risk:RiskCategory ;
      rdfs:label "Adversarial and Security Exploit Risks" ;
      risk:hasRisk
          risk:DataSpecificModelAttacks ,
          risk:AgentIdentityCompromise ,
          risk:OrchestrationInteractionAttacks .

  risk:DataSpecificModelAttacks a risk:PrivacyRisk ;
      rdfs:label "Data-Specific Attacks on Models" ;
      risk:hasSeverity risk:High ;
      risk:frequencyPercent "5"^^xsd:decimal ;
      risk:definition "Targeted attacks on learning or inference processes to extract or manipulate sensitive information." .

  risk:AgentIdentityCompromise a risk:PrivacyRisk ;
      rdfs:label "Agent and Identity Compromise" ;
      risk:hasSeverity risk:High ;
      risk:frequencyPercent "4"^^xsd:decimal ;
      risk:definition "Adversaries impersonate or seize control of agents to gain access to personal data." .

  risk:OrchestrationInteractionAttacks a risk:PrivacyRisk ;
      rdfs:label "Orchestration and Interaction Attacks" ;
      risk:hasSeverity risk:Medium ;
      risk:frequencyPercent "1"^^xsd:decimal ;
      risk:definition "Attacks exploiting coordination, messaging, or orchestration between agents." .
}

